// lib/widgets/registry.ts
// Single source of truth for every widget that exists in this app.
//
// Consumers:
//   - app/widget.tsx            (gallery — derives sections by category + platform)
//   - lib/widgets/snapshot.tsx  (renders each definition × size to a PNG)
//   - lib/widget-data-bridge.ts (decides which native providers to reload)
//   - lib/android-widget-task-handler.tsx (premium gating + thin shells)
//   - widgets/ios/Generated*.swift (Swift mirror, generated by scripts/generate-widget-enum.mjs)
//
// Bump WIDGET_REGISTRY_VERSION whenever you change the visual output of a widget
// (font, layout, anchor coordinates). The snapshot pipeline uses this in its hash
// to decide whether to re-render PNGs.

import type React from 'react';
import type { PreviewSize } from '@/components/widgets/previews/shared';

// Phase E: Hijri SVG height fix, Month Thuluth small wmFs/wmY tweak,
// Azkar font swap WidgetFont2 → Amiri.
// Phase H: prayer/digital previews now honor `forSnapshot` and omit live regions
// so the native overlay no longer ghosts on top of stale digits (constraint C2).
// v4: snapshot host avoids opacity:0 fringe; GlassTile hides shadow during capture.
// v5: PNGs are now transparent foregrounds (root bg + BlurView dropped during
// capture) and keyed per resolved theme — `<id>_<size>_<theme>.png`. Native
// shells paint the themed background underneath so theme changes via iOS
// Edit Widget update the entire widget without a full re-pump.
// v6: verifyAlpha() now runs on tmpUri (app sandbox) instead of App Group path
// so hashes are correctly stored and re-pump is not triggered every launch.
// v7: Thuluth/Hijri previews use larger lineHeight (fs * 1.9) + asymmetric
// paddingTop so calligraphic ascenders (alif tops, harakat) stay inside the
// GlassTile bounds. Hijri watermark + subtitle now use 'هجرياً' instead of 'هجري'/'هـ'.
// v8: Thuluth/Hijri use lineHeight: fs * 1.85 (bbox includes ascenders) WITHOUT
// adjustsFontSizeToFit (was shrinking text to invisibility on medium when bbox
// exceeded available height). No paddingTop on inner View — lineHeight provides
// the headroom internally so glyphs paint within widget bounds.
// v9: Thuluth/Month/Hijri reduce fontSize (38/56→30/46, 26/40→22/32, 20/30→18/26)
// + add paddingTop (22/28) + lineHeight 1.5x + re-enable adjustsFontSizeToFit
// (minScale 0.7). Smaller font means smaller diacritics, paddingTop pushes text
// down inside widget so calligraphic ascenders fit within GlassTile bounds.
// v10: Thuluth/Hijri/Month restore prominent fontSize (34/52, 26/38, 22/32) +
// remove explicit lineHeight (let DecoTypeThuluth font's natural metrics drive)
// + add includeFontPadding:false (Android cleaner alignment) + larger paddingTop
// (32/42 Thuluth, 24/32 MonthSimple, 26/36 Hijri). Auto-fit min 0.75. This
// matches the bold target Thuluth styling without clipping ascenders.
// v11: Move ascender headroom INSIDE the Text element via paddingTop:fs*0.55.
// This shifts glyphs down within the text bbox so calligraphic diacritics paint
// in dedicated padding space above. Parent View paddingTop reduced (14/18) since
// the headroom is now in the Text. Watermark also gets paddingTop:wmFs*0.4.
// v12: Apply the same paddingTop:fs*0.55 ascender-headroom fix to the remaining
// calligraphic watermarks — VersePreview "آيـة اليـوم" + PrayerLarge "الصــلاة" —
// so all RN Text elements using widgetFont/widgetFontL paint diacritics within
// bounds. SVG watermarks are unaffected (explicit baseline positioning).
// v13: Hijri watermark "هجرياً" was clipped horizontally — only "ه" visible
// because calligraphic font at fs=130 was wider than widget. Reduced watermarkFs
// (70/130 → 44/72) + added adjustsFontSizeToFit (min 0.5) so the FULL word
// renders within widget width. Inset by 8px both sides to give visual breathing.
// v14: Hijri watermark + subtitle now read 'هجري' (no tanween). Watermark
// paddingTop bumped 0.5→0.55*fs (matches Thuluth main text) so calligraphic
// ascenders fit inside the bbox. marginTop adjusted in tandem to keep center.
// v15: Added 23 variant-specific Android receivers (RoohDaySimpleSmall, etc.)
// so each widget appears as its own tile in the Android widget picker — was
// previously just 3 generic shells (RoohSmall/Medium/Large).
// v16: Home-screen parity: iOS and Android now expose the same registry set
// (Month Elegant on Android, Daily Dhikr on iOS), plus Android keyguard provider
// names for the same lock-screen content shipped by WidgetKit.
// v17: Android snapshots include the complete rounded preview tile and native
// refresh waits for the active snapshot before rendering.
// v18: Android launcher widget picker uses real per-widget thumbnails instead
// of the generic app-logo preview, with premium thumbnails marked consistently.
// v19: iOS target uses a compiled registry fallback and active snapshot writes
// are awaited before WidgetKit reloads, so Edit Widget / in-app setting changes
// cannot fall back to the default Day Simple tile.
export const WIDGET_REGISTRY_VERSION = 25; // per-widget prayer countdown overlay anchors

export type WidgetCategory = 'date' | 'prayer' | 'quran' | 'azkar' | 'hijri';
export type WidgetPlatform = 'ios' | 'android';
export type WidgetTextColorRole = 'text' | 'muted';
export type WidgetTextAlign = 'left' | 'center' | 'right';

/**
 * Per-size hot-zone metadata for the live native overlay (countdown, time-of-day,
 * etc.). Coordinates are in **logical points** within the widget's rendered size
 * as returned by `getSizeDims(size)` (see components/widgets/previews/shared.ts).
 *
 * The snapshot renderer leaves this region transparent (see C2) so the live
 * native Text drawn at the same coordinates doesn't ghost over stale digits.
 */
export interface WidgetOverlayAnchor {
  /** Centre x of the overlay text (points within widget). */
  x: number;
  /** Baseline y of the overlay text (points within widget). */
  y: number;
  fontSize: number;
  /** PostScript family name. Must be present in both iOS extension and Android widget asset bundle. */
  fontFamily: string;
  align: WidgetTextAlign;
  color: WidgetTextColorRole;
  /** Width of the transparent rectangle the snapshot leaves blank. Defaults to fontSize × 8 if omitted. */
  clearWidth?: number;
  /** Height of the transparent rectangle. Defaults to fontSize × 1.4 if omitted. */
  clearHeight?: number;
}

/**
 * What kind of live data drives the overlay text. Determines how the iOS / Android
 * shell computes the string to draw on top of the snapshot.
 *
 *   - 'prayerCountdown'  → "بعد X س Y د" / "in Xh Ym" — refreshes every minute
 *   - 'prayerNextTime'   → "04:14"        — refreshes every 5 min
 *   - 'currentTime'      → "10:38"        — refreshes every minute
 *
 * Snapshot omits the text when this is set (see C2).
 */
export type WidgetOverlayKind =
  | 'prayerCountdown'
  | 'prayerNextTime'
  | 'currentTime';

export interface WidgetDefinition<TPreviewProps = { size: PreviewSize; language?: 'ar' | 'en' }> {
  /** Stable id used in PNG filenames, intent enums, and analytics. snake-case-free, kebab-allowed. */
  id: string;
  category: WidgetCategory;
  titleAr: string;
  titleEn: string;
  /** Which sizes this widget renders. Drives snapshot output count. */
  sizes: PreviewSize[];
  /** Platforms where this widget is shipped end-to-end. */
  platforms: WidgetPlatform[];
  isPremium: boolean;
  /**
   * When set, only these sizes require an active subscription. When omitted and
   * `isPremium` is true, every size is premium. Use for variants like Day Thuluth
   * (small free / medium gated).
   */
  premiumSizes?: PreviewSize[];
  /** Force the preview / snapshot to render in a specific language regardless of app locale. */
  forcedLanguage?: 'ar' | 'en';
  /** React component that renders the preview tile (also used by snapshot renderer). */
  Preview: React.FC<TPreviewProps>;
  /** Set when the widget includes a value that must update faster than the snapshot cadence. */
  overlay?: {
    kind: WidgetOverlayKind;
    anchors: Partial<Record<PreviewSize, WidgetOverlayAnchor>>;
  };
  /**
   * When true on iOS, the widget extension renders this kind via baked
   * per-state PNGs in `widgets/ios/Assets.xcassets/PrayerStatic/` plus a
   * native numeric overlay (`PrayerStaticOverlay.swift`). The snapshot pump
   * skips capturing runtime PNGs for this kind on iOS. Android continues to
   * consume runtime snapshots until it adopts the same architecture.
   */
  iosStaticPng?: boolean;
  /** Deep link opened when the user taps the widget. */
  deepLink: string;
  /** Optional iOS WidgetKit App Intent enum raw value. Codegen will use definition.id when omitted. */
  iosKind?: string;
  /**
   * Grouped Android provider name. Multiple variants share a provider; the user
   * picks the variant in the configuration activity.
   * Format: `Rooh<Category><Size>`, e.g. `RoohDateSmall`.
   */
  androidProvider?: string;
  /**
   * Legacy Android provider name (one of the 14 originally registered widgets).
   * Kept for backward compatibility with existing home-screen placements. See C3.
   * When present, the legacy provider's renderer delegates to the new pipeline
   * for this `id`.
   */
  legacyAndroidProvider?: string;
}

