/**
 * Android keyguard/lock-screen provider names matching the iOS WidgetKit
 * lock-screen widgets in widgets/ios/WidgetBundle.swift. Android lock-screen
 * widget hosting depends on the device/OS widget host, but these provider
 * entries advertise the same content through WIDGET_CATEGORY_KEYGUARD.
 */
export const ANDROID_LOCK_WIDGET_MAP: Record<string, { id: string; size: PreviewSize }> = {
  RoohLockDayThuluth: { id: 'dayThuluth', size: 'small' },
  RoohLockMonthThuluth: { id: 'monthThuluth', size: 'medium' },
  RoohLockNextPrayer: { id: 'prayerSingle', size: 'small' },
  RoohLockAllPrayers: { id: 'prayerTable', size: 'medium' },
  RoohLockHijriCircular: { id: 'hijriDate', size: 'small' },
  RoohLockNextPrayerCountdown: { id: 'prayerSingle', size: 'small' },
};

export function isAndroidLockWidgetProvider(provider: string): boolean {
  return provider in ANDROID_LOCK_WIDGET_MAP;
}

export function androidWidgetProviderTarget(provider: string): { id: string; size: PreviewSize } | null {
  return LEGACY_ANDROID_WIDGET_MAP[provider] ?? ANDROID_LOCK_WIDGET_MAP[provider] ?? null;
}

export function legacyProviderToRegistryLookup(legacy: string): { id: string; size: PreviewSize } | null {
  return androidWidgetProviderTarget(legacy);
}

/**
 * Single source of truth for "is this widget unlocked for the current user".
 */
export function isWidgetUnlocked(def: WidgetDefinition, isPremium: boolean, size: PreviewSize): boolean {
  return !premiumRequiredForSize(def, size) || isPremium;
}

/**
 * Stable, content-aware key for cache invalidation. Bumping
 * WIDGET_REGISTRY_VERSION (see top of file) automatically invalidates every
 * snapshot. Caller should append per-user signature (theme/lang/etc.) — see
 * lib/widgets/snapshot.tsx#computeHash.
 */
export function registryFingerprint(): string {
  const ids = WIDGET_REGISTRY.map((d) => `${d.id}:${d.sizes.join(',')}`).sort().join('|');
  return `v${WIDGET_REGISTRY_VERSION}:${ids}`;
}
